input.sparql:
SELECT ?point ?class ?ts WHERE {
  ?z a brick:Zone ; brick:hasSubclass* ?z .
  FILTER(regex(str(?z), "Perimeter_bot_ZN_2|DataCenter_mid_ZN_6"))
}

SELECT ?s ?rel ?loc WHERE {
  ?s a brick:Air_Temperature_Sensor .
  ?s ?rel ?loc .
  FILTER(str(?loc) CONTAINS "Zone_F2_Z03" )
}

SELECT ?s ?ts WHERE {
  ?s a brick:Air_Temperature_Sensor .
  ?s rdfs:label ?l .
  FILTER(regex(str(?s), "Zone_F2_Z03|Zone_F2_Z08"))
  ?s ref:hasExternalReference/ref:hasTimeseriesId ?ts .
}

SELECT ?s ?loc WHERE {
  ?s a brick:Air_Temperature_Sensor .
  ?s ?p ?loc .
  FILTER(str(?loc) != "https://brickschema.org/schema/Brick#Air_Temperature_Sensor" && str(?loc) != "http://qudt.org/vocab/unit/DEG_C" && str(?loc) != "http://qudt.org/vocab/quantitykind/Temperature")
}

